 {Controls c;assert(c.Admit(1,7));assert(!c.Bind(1,6,"frame","session","loader",1,"identity"));assert(!c.Bind(1,7,"","session","loader",1,"identity"));assert(!c.Bind(1,7,"frame","session","loader",1,""));assert(c.Bind(1,7,"frame","session","loader",1,"main"));assert(c.InFrame("frame")==std::vector<Controls::Identity>({{1,7}}));assert(c.InFrame("other").empty());assert(c.InContext("session",1,"main")==std::vector<Controls::Identity>({{1,7}}));assert(c.InContext("session",2).empty()&&c.InContext("other").empty());}
 {Controls c;assert(c.Admit(1,1));assert(!Controls::Gone(*c.Get(1),{}));assert(c.Bind(1,1,"frame","session","loader",8,"old-unique"));const auto scope=*c.Get(1);assert(Controls::Gone(scope,{}));Controls::Current current{"session","loader","main","old-unique",7,8};assert(!Controls::Gone(scope,current));current.utility_identity="reused-context-new-unique";assert(Controls::Gone(scope,current));current.utility_identity="old-unique";current.loader="next-document";assert(Controls::Gone(scope,current));current.loader="loader";current.session="next-target";assert(Controls::Gone(scope,current));}
 {Controls c;assert(c.Admit(1,1)&&c.Admit(2,9));assert(c.Bind(1,1,"parent","session","loader",5,"main"));assert(c.Bind(2,9,"child","session","loader",6,"child"));assert(c.InContext("session").size()==2);assert(c.Bind(1,1,"parent","session","loader",7,"utility"));assert(c.InContext("session",5).empty());assert(c.InContext("session",7,"utility")==std::vector<Controls::Identity>({{1,1}}));assert(c.InFrame("child")==std::vector<Controls::Identity>({{2,9}}));}
 {Controls c;assert(c.Admit(1,7));assert(!c.Validated(1,7)&&!c.MarkValidated(1,8));assert(c.MarkValidated(1,7));assert(c.Bind(1,7,"frame","session","loader",8,"new-unique"));assert(c.Validated(1,7));assert(c.InContext("session",8,"old-unique").empty()&&c.InContext("session",8).empty());assert(c.InContext("session",8,"new-unique")==std::vector<Controls::Identity>({{1,7}}));c.Remove(1,8);assert(c.Validated(1,7));c.Remove(1,7);assert(c.Admit(1,8)&&!c.Validated(1,8));}
